        }
        onlineFeature?.let{feature->OnlineSignInDialog(feature,model,scope){onlineFeature=null}}
    }
}
@Composable fun Home(tasks:List<Task>,sessions:List<Session>,edit:(Task)->Unit,capture:()->Unit,inventory:()->Unit,shopping:()->Unit,calendar:()->Unit,taskList:()->Unit,spaces:()->Unit,count:Int,buyCount:Int,saveSession:(Session)->Unit,focus:()->Unit){
    val today=LocalDate.now();val active=tasks.filter{it.status !in listOf(Status.DONE,Status.ARCHIVED)};val now=sessions.filter{sessionDate(it.start)==today}.sortedBy{it.start};val done=now.count{it.done};val progress by animateFloatAsState(if(now.isEmpty())0f else done.toFloat()/now.size,label="daily progress")
    LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(20.dp),verticalArrangement=Arrangement.spacedBy(15.dp)){
        item{Text(today.format(DateTimeFormatter.ofPattern("EEEE, d MMMM",java.util.Locale("es","ES"))).replaceFirstChar{it.uppercase()},color=MaterialTheme.colorScheme.onSurfaceVariant,style=MaterialTheme.typography.labelLarge);Text("Mi día",style=MaterialTheme.typography.headlineLarge)}
        item{Surface(Modifier.fillMaxWidth().clickable{calendar()},shape=RoundedCornerShape(28.dp),color=soft(Blue,.18f)){Column(Modifier.padding(20.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){Row(verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text("TU PLANIFICACIÓN",style=MaterialTheme.typography.labelMedium,color=MaterialTheme.colorScheme.onSurfaceVariant);Text("$done de ${now.size} sesiones",style=MaterialTheme.typography.headlineMedium);Text("${now.filterNot{it.done}.sumOf{(it.end-it.start)/60000}} min pendientes hoy",style=MaterialTheme.typography.bodyMedium)};Box(contentAlignment=Alignment.Center){CircularProgressIndicator(progress={progress},modifier=Modifier.size(72.dp),strokeWidth=7.dp,trackColor=soft(Blue,.27f));Text("${(progress*100).toInt()}%",style=MaterialTheme.typography.titleMedium)}};LinearProgressIndicator(progress={progress},modifier=Modifier.fillMaxWidth().height(7.dp).clip(RoundedCornerShape(9.dp)));Row{Text("${active.size} tareas pendientes",Modifier.weight(1f),style=MaterialTheme.typography.labelLarge);Icon(Icons.Default.ArrowForward,null)}}}}
        item{Row(verticalAlignment=Alignment.CenterVertically){Text("Agenda de hoy",Modifier.weight(1f),style=MaterialTheme.typography.titleLarge);TextButton(onClick=calendar){Text("Ver agenda")}};if(now.isEmpty())GlassCard{Text("Un día por organizar",style=MaterialTheme.typography.titleMedium);Text("Añade una tarea y crea sesiones según tus horas disponibles.");TextButton(onClick=capture){Icon(Icons.Default.Add,null);Text(" Añadir pendiente")}}}
        items(now,key={"today-${it.id}"}){s->val t=tasks.find{it.id==s.taskId};Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Column(Modifier.width(55.dp)){Text(time(s.start),style=MaterialTheme.typography.titleSmall);Text(time(s.end),style=MaterialTheme.typography.labelSmall)};Box(Modifier.width(4.dp).height(58.dp).clip(RoundedCornerShape(4.dp)).background(t?.let{categoryColor(it.category)}?:Blue));Spacer(Modifier.width(8.dp));GlassCard(Modifier.weight(1f).clickable{t?.let(edit)},t?.let{categoryColor(it.category)}?:Blue){Row(verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(t?.title?:"Tarea no disponible",style=MaterialTheme.typography.titleMedium);Text("${(s.end-s.start)/60000} min",style=MaterialTheme.typography.labelSmall)};Checkbox(s.done,{saveSession(s.copy(done=it))})}}}}
        item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){FilledTonalButton(onClick=capture,modifier=Modifier.weight(1f)){Icon(Icons.Default.Add,null);Text(" Añadir tarea")};OutlinedButton(onClick=focus,modifier=Modifier.weight(1f)){Icon(Icons.Default.Timer,null);Text(" Concentración")}}}
        item{Text("En casa",style=MaterialTheme.typography.titleLarge);Spacer(Modifier.height(8.dp));Row(horizontalArrangement=Arrangement.spacedBy(10.dp)){DashboardTile("Hogar","$count objetos",Icons.Default.Home,Peach,Modifier.weight(1f),inventory);DashboardTile("Compra","$buyCount pendientes",Icons.Default.ShoppingCart,Mint,Modifier.weight(1f),shopping)}}
        item{Text("Próximas fechas límite",style=MaterialTheme.typography.titleLarge);if(active.none{it.due.isNotBlank()})Text("No tienes fechas límite pendientes.",color=MaterialTheme.colorScheme.onSurfaceVariant)}
        items(active.filter{it.due.isNotBlank()}.sortedBy{it.due}.take(8),key={it.id}){TaskCard(it){edit(it)}}
    }
}
