@Composable fun TaskCard(t:Task,onClick:()->Unit){val tint=categoryColor(t.category);val p by animateFloatAsState(t.progress(),label="task progress");GlassCard(Modifier.clickable(onClick=onClick),tint){Row(verticalAlignment=Alignment.CenterVertically){Surface(shape=RoundedCornerShape(14.dp),color=soft(tint,.18f)){Icon(if(t.status==Status.DONE)Icons.Default.CheckCircle else if(t.phases.isNotEmpty())Icons.Default.Folder else Icons.Default.Checklist,null,Modifier.padding(11.dp).size(22.dp),tint=tint)};Spacer(Modifier.width(12.dp));Column(Modifier.weight(1f)){Text(t.title,style=MaterialTheme.typography.titleMedium);Text("${t.category.label} · ${t.status.label}",style=MaterialTheme.typography.labelSmall,color=MaterialTheme.colorScheme.onSurfaceVariant)};Icon(Icons.Default.ChevronRight,null)};if(t.description.isNotBlank())Text(t.description,maxLines=2,overflow=TextOverflow.Ellipsis);Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){if(t.due.isNotBlank())Text("${t.due}",color=tint,style=MaterialTheme.typography.labelLarge);if(t.minutes>0)Text("${t.minutes} min",style=MaterialTheme.typography.labelLarge);if(t.priority.ordinal>=Priority.HIGH.ordinal)Text(t.priority.label,color=MaterialTheme.colorScheme.error,style=MaterialTheme.typography.labelLarge)};if(t.checks.isNotEmpty()||t.phases.isNotEmpty()){LinearProgressIndicator(progress={p},modifier=Modifier.fillMaxWidth().height(5.dp).clip(RoundedCornerShape(8.dp)),color=tint);Text("${(p*100).toInt()}% completado",style=MaterialTheme.typography.labelSmall)}}}
@Composable fun TaskList(tasks:List<Task>,edit:(Task)->Unit,add:()->Unit){var q by remember{mutableStateOf("")};var filter by remember{mutableStateOf("Pendientes")};val categories=listOf("Pendientes","Completadas","Todas","Más filtros");var more by remember{mutableStateOf(false)}
    val shown=tasks.filter{t->(q.isBlank()||listOf(t.title,t.description,t.tags.joinToString()).any{it.contains(q,true)})&&when(filter){"Pendientes"->t.status !in listOf(Status.DONE,Status.ARCHIVED);"Todas"->t.status!=Status.ARCHIVED;"Completadas"->t.status==Status.DONE;"Archivadas"->t.status==Status.ARCHIVED;"Atrasadas"->t.due.isNotBlank()&&t.due<LocalDate.now().toString()&&t.status !in listOf(Status.DONE,Status.ARCHIVED);else->t.category.label==filter&&t.status!=Status.ARCHIVED}}.sortedWith(compareBy<Task>{it.status==Status.DONE}.thenBy{it.due.ifBlank{"9999"}}.thenByDescending{it.priority.ordinal})
    LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(18.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{Section("Mis tareas");Field(q,{q=it},"Buscar tareas o etiquetas");Row(Modifier.horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(6.dp)){categories.forEach{c->FilterChip(filter==c||c=="Más filtros"&&more,{if(c=="Más filtros")more=!more else filter=c},label={Text(c)})}};if(more)Row(Modifier.horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(6.dp)){listOf("Bandeja","Con fecha límite","Próximamente","Sin fecha","Archivadas","Atrasadas").forEach{c->FilterChip(filter==c,{filter=c},label={Text(c)})}};Text("${shown.size} tareas",style=MaterialTheme.typography.labelMedium);if(shown.isEmpty()){Spacer(Modifier.height(16.dp));GlassCard{Text("Nada por aquí",style=MaterialTheme.typography.titleMedium);Text("Añade lo que tienes en mente o cambia el filtro.");TextButton(onClick=add){Text("Añadir tarea")}}}};items(shown,key={it.id}){TaskCard(it){edit(it)}}}
}
